const CATEGORIAS = {
  campo: { nombre: 'Campo y Jardín', pagina: 'campo-jardin.html' },
  agua: { nombre: 'Manejo de Agua', pagina: 'manejo-agua.html' },
  energia: { nombre: 'Manejo de Energía', pagina: 'manejo-energia.html' },
  fumigacion: { nombre: 'Fumigación', pagina: 'fumigacion.html' },
  construccion: { nombre: 'Construcción', pagina: 'construccion.html' },
  ferreteria: { nombre: 'Ferretería', pagina: 'ferreteria.html' },
  accesorios: { nombre: 'Accesorios', pagina: 'accesorios.html' },
  lubricantes: { nombre: 'Lubricantes', pagina: 'lubricantes.html' },
  repuestos: { nombre: 'Repuestos', pagina: 'repuestos.html' }
};

function formatoCOP(n) { return Number(n).toLocaleString('es-CO', { style: 'currency', currency: 'COP', maximumFractionDigits: 0 }); }

function descuentoDe(p) { return p.precioAntes > p.precio ? Math.round((p.precioAntes - p.precio) / p.precioAntes * 100) : 0; }

/* Una sola etiqueta por producto, en este orden: agotado > descuento > nuevo > popular */
function etiquetaDe(p) {
  if (!p.disponible) return { texto: 'AGOTADO', clase: 'agotado' };
  const d = descuentoDe(p);
  if (d) return { texto: `-${d}%`, clase: 'descuento' };
  if (p.etiqueta === 'nuevo') return { texto: 'NUEVO', clase: 'nuevo' };
  if (p.etiqueta === 'popular') return { texto: 'POPULAR', clase: 'popular' };
  return null;
}

/* Enlace a la categoría del producto, ya filtrada por su nombre */
function urlDe(p) { return `${CATEGORIAS[p.cat].pagina}?search=${encodeURIComponent(p.titulo)}`; }

function escHTML(s) { return String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]); }
